let dmLobby=null,dmLobbyHero=null,dmLobbyPrevious=null,dmLobbyStarting=false;
function dmEntranceHtml(){const p=PLACES.deadm;if(!p||(S.mapZ||viewZone())!==p.z)return '';return '<button type="button" id="dm-map-entry" class="qn grp" data-dungeon-entry="deadmines" style="left:'+p.x+'%;top:'+p.y+'%" aria-label="Мёртвые копи: состав, боссы и добыча"><span class="mk" aria-hidden="true">Вход</span><span class="nmx">Мёртвые копи</span></button>';}
function dmLobbyAllowed(){return !!S.hero&&!S.walk&&!S.amb&&!run&&!playing&&!tavBusy&&!S.pick&&$('battle').hidden;}
function dmLobbyRender(){if(!dmLobby||!dmLobby.open||S.hero!==dmLobbyHero)return;const d=B.DUNGEONS.deadmines,rooms=d.rooms,optional=(d.optional||[]).filter(k=>B.ENCOUNTERS[k]);dmLobby.innerHTML='<header><h2>Мёртвые копи</h2></header><p>Западный край · рекомендуется '+d.level+' ур. · до '+d.size+' героев</p><p>'+rooms.length+' основных комнат / боссов + '+optional.length+' необязательный · отдыхов: '+d.rests+'</p><section class="box"><h3>Ваш отряд</h3><div data-dm-party></div><p class="hint" data-dm-roles></p></section><section class="box"><h3>Маршрут и боссы</h3><ol data-dm-bosses></ol></section><section class="box"><h3>Добыча</h3><p>После победы — один предмет для класса и основной характеристики главного героя. Он идёт в сумку; надеть можно между боями. Повторная обработка победы не выдаёт награду снова.</p><p class="hint">Авторские тестовые предметы и характеристики, не точная база Classic.</p><div data-dm-loot></div></section><section class="box"><h3>Правила забега</h3><p>Опыт за основные комнаты: '+B.dungeonXp(S.level,'deadmines')+'. Необязательный босс даёт опыт отдельно. Награда за квест — отдельно и один раз.</p><p>Здоровье и мана переносятся. После комнаты живые восстанавливают до '+Math.round(B.RECOVERY.hp*100)+'% максимума ХП и '+Math.round(B.RECOVERY.mana*100)+'% маны, не выше максимума. Павшие сами не встают. Отдых полностью восстанавливает отряд; доступно '+d.rests+'. Смена вещей не лечит.</p><p>Можно выйти между боями с полученными вещами. Перезагрузка страницы не продолжает текущий забег: сохраняются герой и добыча, но не позиция в инсте.</p></section><footer></footer>';dmLobby.querySelector('header').append(gearButton('Закрыть',()=>dmLobby.close()));const party=dmLobby.querySelector('[data-dm-party]'),roles={tank:0,heal:0,dd:0};S.party.forEach((k,i)=>{const cls=clsOf(k),sp=B.specOf(cls,specKey(k));roles[sp.role]++;const b=gearButton((i===0?'Вы: ':'')+(heroName(k)||B.CLASSES[cls].name)+' · '+hLevel(k)+' ур. · '+RN[sp.role],()=>{if(dmLobbyAllowed()&&i>0)azOpen(i,b);});b.disabled=i===0;b.dataset.dmSlot=String(i);party.append(b);});if(S.party.length<d.size){const b=gearButton('+ Добавить соратника',()=>{if(dmLobbyAllowed())azOpen(S.party.length,b);});b.dataset.dmAdd='';party.append(b);}dmLobby.querySelector('[data-dm-roles]').textContent='Танки: '+roles.tank+' · Лекари: '+roles.heal+' · Бойцы: '+roles.dd+'.'+(!roles.tank?' Нет танка.':'')+(!roles.heal?' Нет лекаря.':'');const route=dmLobby.querySelector('[data-dm-bosses]'),loot=dmLobby.querySelector('[data-dm-loot]');rooms.concat(optional).forEach(k=>{const e=B.ENCOUNTERS[k],li=document.createElement('li');li.textContent=e.name+' · '+e.level+' ур.'+(optional.includes(k)?' · необязательный, перед Ван Клифом':'')+' — '+(e.tip||e.text||'');route.append(li);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=e.name;details.append(summary);dmCatalogue().filter(i=>i.bossSource===k).forEach(item=>{const p=document.createElement('p');p.style.color=item.color;const stats=[['armorFlat','Броня'],['stamina','Выносливость'],['strength','Сила'],['agility','Ловкость'],['intellect','Интеллект']].filter(([key])=>item[key]).map(([key,label])=>label+' +'+item[key]);p.textContent=item.name+' · '+item.label+' · с '+item.requiredLevel+' ур. · '+stats.join(', ')+' · классы: '+item.allowedClasses.map(cls=>B.CLASSES[cls].name).join(', ');details.append(p);});loot.append(details);});const start=gearButton('Начать забег',()=>{if(!dmLobbyAllowed()||S.hero!==dmLobbyHero||S.party.length>d.size)return;dmLobbyStarting=true;dmLobby.close();if(!enterFreeDeadmines()){dmLobbyStarting=false;dmOpenLobby();}});start.dataset.dmStart='';start.disabled=!dmLobbyAllowed()||S.party.length>d.size;dmLobby.querySelector('footer').append(start);}
function dmOpenLobby(){if(!dmLobbyAllowed())return false;if(dmLobby?.open){dmLobbyRender();return true;}if(!dmLobby){dmLobby=document.createElement('dialog');dmLobby.id='dm-lobby';dmLobby.className='az-sheet';dmLobby.style.cssText='width:min(900px,94vw);max-height:90dvh;overflow:auto;box-sizing:border-box';dmLobby.setAttribute('aria-label','Подготовка: Мёртвые копи');document.body.append(dmLobby);dmLobby.addEventListener('close',()=>{if(!dmLobbyStarting&&S.hero===dmLobbyHero)S.enc=dmLobbyPrevious;dmLobbyHero=null;dmLobbyPrevious=null;});}dmLobbyHero=S.hero;dmLobbyPrevious=S.enc;dmLobbyStarting=false;S.enc='dungeon:deadmines';S.qopen=false;$('qsheet').hidden=true;document.body.classList.remove('qlock');dmLobby.showModal();dmLobbyRender();return true;}
function dmInstallLobby(){azPick.addEventListener('close',()=>{if(dmLobby?.open)dmLobbyRender();});$('world').addEventListener('click',event=>{if(!event.target.closest('[data-dungeon-entry="deadmines"]'))return;event.preventDefault();event.stopImmediatePropagation();dmOpenLobby();},true);}
